.toast-container {
  position: fixed;
  z-index: 2147483000;
  inset: 16px auto auto 50%;
  display: block;
  width: min(480px, calc(100vw - 28px));
  margin: 0;
  padding: 0;
  overflow: visible;
  border: 0;
  background: transparent;
  color: inherit;
  transform: translateX(-50%);
  pointer-events: none;
}

.toast {
  display: grid;
  width: 100%;
  min-width: 0;
  grid-template-columns: 42px minmax(0, 1fr) 8px;
  align-items: center;
  gap: 11px;
  padding: 11px 13px;
  border: 1px solid rgba(43, 178, 145, 0.28);
  border-radius: 17px;
  background: rgba(250, 255, 253, 0.97);
  box-shadow: 0 16px 44px rgba(14, 83, 83, 0.18);
  direction: rtl;
  animation: naw-feedback-in-v336 180ms ease both;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.toast.is-hiding {
  animation: naw-feedback-out-v336 180ms ease both;
}

.naw-feedback-icon-v336 {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 13px;
  background: linear-gradient(135deg, #dff8f4, #e9fbef);
  color: #10966f;
}

.naw-feedback-icon-v336 svg {
  width: 20px;
  height: 20px;
}

.naw-feedback-copy-v336 {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.naw-feedback-copy-v336 strong {
  display: -webkit-box;
  overflow: hidden;
  color: #184b4a;
  font-size: 12px;
  font-weight: 900;
  line-height: 1.55;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  white-space: normal;
}

.naw-feedback-copy-v336 small {
  overflow: hidden;
  color: #6f8583;
  font-size: 9px;
  font-weight: 700;
  line-height: 1.5;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.naw-feedback-dot-v336 {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #21bf7b;
  box-shadow: 0 0 0 5px rgba(33, 191, 123, 0.12);
}

.naw-feedback-v336.is-error {
  border-color: rgba(220, 71, 71, 0.25);
  background: rgba(255, 251, 251, 0.98);
}

.naw-feedback-v336.is-error .naw-feedback-icon-v336 {
  background: #fff0f0;
  color: #d44747;
}

.naw-feedback-v336.is-error .naw-feedback-copy-v336 strong {
  color: #963737;
}

.naw-feedback-v336.is-error .naw-feedback-dot-v336 {
  background: #d44747;
  box-shadow: 0 0 0 5px rgba(212, 71, 71, 0.1);
}

.naw-feedback-v336.is-warning {
  border-color: rgba(220, 151, 35, 0.28);
  background: rgba(255, 253, 247, 0.98);
}

.naw-feedback-v336.is-warning .naw-feedback-icon-v336 {
  background: #fff5dc;
  color: #c47c0a;
}

.naw-feedback-v336.is-warning .naw-feedback-copy-v336 strong {
  color: #81530d;
}

.naw-feedback-v336.is-warning .naw-feedback-dot-v336 {
  background: #e6a126;
  box-shadow: 0 0 0 5px rgba(230, 161, 38, 0.12);
}

.naw-feedback-v336.is-info {
  border-color: rgba(34, 151, 197, 0.25);
  background: rgba(249, 253, 255, 0.98);
}

.naw-feedback-v336.is-info .naw-feedback-icon-v336 {
  background: #e9f7fc;
  color: #168bb5;
}

.naw-feedback-v336.is-info .naw-feedback-dot-v336 {
  background: #2297c5;
  box-shadow: 0 0 0 5px rgba(34, 151, 197, 0.11);
}

@keyframes naw-feedback-in-v336 {
  from { opacity: 0; transform: translateY(-14px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes naw-feedback-out-v336 {
  from { opacity: 1; transform: translateY(0); }
  to { opacity: 0; transform: translateY(-10px); }
}

@media (prefers-reduced-motion: reduce) {
  .naw-feedback-v336,
  .naw-feedback-v336.is-hiding {
    animation-duration: 1ms;
  }
}

.sidebar-overlay {
