}

@media (max-width: 700px) {
  .topbar { min-height: 70px; padding: 11px 15px; }
  .page-heading p { display: none; }
  .page-heading h1 { font-size: 17px; }
  .content { padding: 16px 14px 35px; }
  .quick-add-text { display: none; }
  .topbar .primary-btn { width: 42px; padding: 0; }
  .topbar .primary-btn span:last-child { display: none; }
  .welcome-banner { min-height: 210px; padding: 25px; }
  .welcome-banner h2 { font-size: 22px; }
  .banner-art { position: absolute; left: -65px; opacity: 0.5; transform: scale(0.75); }
  .stats-grid,
  .attendance-kpis,
  .payroll-summary,
  .department-grid { grid-template-columns: 1fr 1fr; }
  .section-toolbar { align-items: stretch; flex-direction: column; }
  .toolbar-filters { display: grid; grid-template-columns: 1fr 1fr; }
  .toolbar-filters .search-field { width: 100%; grid-column: 1 / -1; }
  .toolbar-actions { justify-content: flex-end; }
  .employee-summary-row { gap: 12px; overflow-x: auto; }
  .employee-summary-row > i { display: none; }
  .view-switcher { min-width: 68px; }
  .employee-cards { grid-template-columns: 1fr; }
  .leave-request { grid-template-columns: auto 1fr; }
  .leave-request-actions { grid-column: 1 / -1; justify-content: flex-end; }
  .payroll-hero { grid-template-columns: 1fr; }
  .payroll-meta { grid-column: 1; grid-row: auto; flex-wrap: wrap; justify-content: flex-start; }
  .form-grid { grid-template-columns: 1fr; }
  .full-field { grid-column: 1; }
  .form-grid-3,
  .form-grid-4 { grid-template-columns: 1fr; }
  .span-2,
  .span-3 { grid-column: 1; }
  .employee-photo-row { align-items: flex-start; flex-wrap: wrap; }
  .employee-photo-copy { min-width: calc(100% - 92px); }
  .file-button { margin-right: 89px; }
  .remove-photo-btn { align-self: center; }
  .bank-fields { grid-template-columns: 1fr; }
  .bank-fields > label:last-child { grid-column: 1; }
  .note-composer { grid-template-columns: 1fr; }
  .note-composer .primary-btn { justify-self: end; }
  .section-title-with-action { align-items: flex-start; flex-wrap: wrap; }
  .section-title-with-action .secondary-btn { margin-right: 49px; }
}

@media (max-width: 480px) {
  .stats-grid,
  .attendance-kpis,
  .payroll-summary,
  .department-grid { grid-template-columns: 1fr; }
  .notification-btn { display: none; }
  .welcome-banner { min-height: 230px; }
  .panel-head { align-items: flex-start; }
  .panel-head .secondary-btn { padding: 0 10px; }
