  width: min(850px, calc(100vw - 30px));
}

.clearance-sheet {
  padding: 20px;
  border: 1px solid var(--border);
  color: #1d292d;
}

.clearance-title {
  margin: 0 0 5px;
  color: var(--primary-dark);
  font-size: 19px;
  text-align: center;
}

.clearance-subtitle {
  margin: 0 0 16px;
  color: var(--muted);
  font-size: 9px;
  text-align: center;
}

.clearance-section {
  margin-top: 13px;
}

.clearance-section h4 {
  margin: 0 0 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
  font-size: 10px;
}

.clearance-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.clearance-grid div {
  padding: 7px;
  border-radius: 6px;
  background: #f6f8f8;
}

.clearance-grid span {
  display: block;
  color: var(--muted);
  font-size: 7px;
}

.clearance-grid strong {
  display: block;
  margin-top: 3px;
  font-size: 8px;
}

.clearance-grid .clearance-wide {
  grid-column: 1 / -1;
}

.clearance-declaration {
  margin: 13px 0;
  font-size: 9px;
  line-height: 1.9;
  text-align: justify;
}

.clearance-auth {
  display: flex;
  min-height: 90px;
  align-items: end;
  justify-content: space-around;
  gap: 20px;
  text-align: center;
}

.clearance-auth img {
  display: block;
  max-width: 130px;
  max-height: 70px;
  margin: 0 auto 5px;
  object-fit: contain;
}

.three-choices {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.employee-number-cell {
  display: flex;
  flex-direction: column;
}

.employee-number-cell strong {
  direction: ltr;
  font-size: 10px;
}

.employee-number-cell small {
  margin-top: 4px;
  color: var(--muted);
  font-size: 7px;
}

@media (max-width: 1100px) {
  .employee-workspace {
    grid-template-columns: 195px minmax(0, 1fr);
  }

  .form-grid-4 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .bank-fields {
    grid-template-columns: 1fr 1.2fr;
  }

  .bank-fields > label,
  .bank-fields > button {
    grid-column: auto;
  }

  .repeatable-row,
  .repeatable-row.document-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .repeatable-row .row-delete-btn {
    position: absolute;
    top: 10px;
    left: 10px;
  }
}

@media (max-width: 720px) {
  .employee-profile-modal {
    width: calc(100vw - 18px);
    height: calc(100vh - 18px);
  }

  .employee-workspace {
    display: flex;
    flex-direction: column;
  }

  .employee-form-sidebar {
    display: grid;
    grid-template-columns: 64px minmax(0, 1fr);
    align-items: center;
    gap: 5px 12px;
    padding: 12px;
    overflow: visible;
    border-bottom: 1px solid var(--border);
    border-left: 0;
  }

  .employee-side-photo {
    width: 62px;
    height: 62px;
    grid-row: span 4;
  }

  .employee-photo-upload,
  .employee-photo-remove {
    display: none;
  }

  .employee-side-number,
  .employee-side-service {
    margin: 0;
  }

  .employee-section-nav {
    grid-column: 1 / -1;
    display: flex;
    margin-top: 7px;
    padding-top: 9px;
    overflow-x: auto;
    flex-direction: row;
  }

  .employee-section-nav button {
    flex: 0 0 auto;
    white-space: nowrap;
  }

  .employee-section-content {
    padding: 10px;
  }

  .employee-tab-panel {
    padding: 14px;
  }

  .form-grid-3,
  .form-grid-4,
  .documentation-grid,
  .quick-profile-data {
    grid-template-columns: 1fr;
  }

  .span-2,
  .span-all {
    grid-column: 1;
  }

  .bank-fields,
  .repeatable-row,
  .repeatable-row.document-row {
    grid-template-columns: 1fr;
  }

  .quick-profile {
    grid-template-columns: 1fr;
  }

  .quick-profile-photo {
    margin: auto;
  }

  .three-choices {
    grid-template-columns: 1fr;
  }

  .clearance-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

:root {
  --bg: #f3f5f8;
  --surface: #ffffff;
  --surface-soft: #f8fafc;
  --border: #dce3ec;
  --text: #172033;
  --muted: #7f889a;
  --primary: #1294b8;
  --primary-dark: #0b748f;
  --primary-soft: #e8f8fb;
  --accent-blue: #18aee1;
  --accent-green: #20c86e;
  --sidebar-bg: #0d172c;
  --shadow: 0 12px 34px rgba(38, 55, 83, 0.08);
  --radius: 18px;
  --sidebar-width: 282px;
  --topbar-height: 92px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  overflow: hidden !important;
  clip: rect(0 0 0 0) !important;
  white-space: nowrap !important;
}

body {
  background: var(--bg);
}

.topbar {
  position: fixed;
  inset: 0 0 auto;
  z-index: 70;
  min-height: var(--topbar-height);
  padding: 14px 30px;
  border-bottom: 1px solid #dfe5ed;
  background: #fff;
  box-shadow: 0 1px 0 rgba(32, 49, 76, 0.03);
  backdrop-filter: none;
}

.topbar-start {
  min-width: 280px;
}

.page-heading h1 {
  color: #13778c;
  font-size: clamp(21px, 2vw, 30px);
  font-weight: 800;
}

.page-heading p {
  color: #7c8595;
  font-size: 12px;
  font-weight: 700;
}

.topbar-utility-hidden {
  display: none !important;
}

.topbar-user {
  display: flex;
  align-items: center;
  gap: 11px;
  direction: ltr;
}

.topbar-user-mark {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(145deg, var(--accent-blue), var(--accent-green));
  color: #fff;
  font-size: 19px;
  font-weight: 800;
  box-shadow: 0 6px 18px rgba(24, 174, 225, 0.2);
}

.topbar-user-copy {
  display: flex;
  align-items: flex-start;
  direction: rtl;
  flex-direction: column;
}

.topbar-user-copy strong {
  color: #1f2939;
  font-size: 13px;
}

.topbar-user-copy span {
  margin-top: 2px;
  color: #7d8798;
  font-size: 10px;
}

.logout-btn {
  display: grid;
  width: 40px;
  height: 40px;
  margin-right: 5px;
  place-items: center;
  border: 1px solid #f2d7d7;
  border-radius: 50%;
  background: #fff6f6;
  color: #d23838;
}

.logout-btn svg {
  width: 19px;
}

.sidebar {
  inset: var(--topbar-height) 0 0 auto;
  width: var(--sidebar-width);
  height: calc(100vh - var(--topbar-height));
  padding: 0 14px 22px;
  background: var(--sidebar-bg);
  color: #fff;
  box-shadow: -5px 0 24px rgba(10, 20, 39, 0.08);
}

.sidebar-heading {
  margin: 0 -14px 14px;
  padding: 21px 25px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  color: #fff;
  font-size: 16px;
  font-weight: 800;
}

.main-nav {
  gap: 7px;
}

.nav-item {
  min-height: 49px;
  gap: 14px;
  padding: 0 17px;
  border-radius: 13px;
  color: #e3e7ef;
  font-size: 13px;
  font-weight: 700;
}

.nav-item:hover {
  background: rgba(255, 255, 255, 0.07);
}

.nav-item.active {
  background: linear-gradient(100deg, var(--accent-blue), var(--accent-green));
  color: #fff;
  box-shadow: 0 7px 18px rgba(20, 183, 173, 0.17);
}

.nav-item.active::before {
  display: none;
}

.nav-icon,
.nav-icon svg {
  width: 19px;
  height: 19px;
}

.nav-count {
  background: rgba(255, 255, 255, 0.2);
  color: #fff;
}

.nav-label {
  margin: 21px 17px 7px;
  color: #7e899f;
  font-size: 9px;
}

.main-area {
  min-height: 100vh;
  margin-right: var(--sidebar-width);
  padding-top: var(--topbar-height);
}

.content {
  max-width: 1720px;
  padding: 28px 28px 54px;
}

.panel,
.stat-card,
.section-toolbar,
.employee-summary-row,
.leave-balance-card,
.leave-list-panel,
.payroll-hero,
.settings-layout,
.welcome-banner {
  border-color: var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.primary-btn {
  background: linear-gradient(100deg, var(--accent-blue), var(--accent-green));
  box-shadow: 0 8px 20px rgba(24, 184, 170, 0.19);
}

.primary-btn:hover {
  background: linear-gradient(100deg, #119fd0, #18b961);
}

.secondary-btn {
  border-color: #e0e4ea;
  background: #e9ebef;
  color: #3e4759;
}

button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline-color: rgba(24, 174, 225, 0.23);
}

.employee-profile-modal[open] {
  position: fixed;
  inset: var(--topbar-height) var(--sidebar-width) 0 0;
  width: auto;
  height: auto;
  max-width: none;
  max-height: none;
  margin: 0;
  overflow: hidden;
  border-radius: 0;
  background: var(--bg);
  box-shadow: none;
}

.employee-profile-modal::backdrop {
  background: transparent;
  backdrop-filter: none;
}

.employee-profile-modal form {
  height: 100%;
}

.employee-profile-modal .modal-head {
  min-height: 98px;
  padding: 25px 30px 14px;
  border: 0;
  background: var(--bg);
  backdrop-filter: none;
}

.employee-profile-modal .modal-head h2 {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #182033;
  font-size: 22px;
}

.employee-profile-modal .modal-head h2 svg {
  width: 26px;
  color: #147d91;
}

.employee-profile-modal .modal-head p {
  margin-top: 7px;
  color: #7b8495;
  font-size: 11px;
}

.employee-profile-modal .modal-head .icon-btn {
  border-color: #dfe4eb;
  border-radius: 10px;
  background: #fff;
}

.employee-workspace {
  grid-template-columns: 310px minmax(0, 1fr);
  gap: 17px;
  padding: 0 28px 18px;
  background: var(--bg);
}

.employee-form-sidebar {
  align-items: stretch;
  padding: 20px 17px;
  border: 1px solid var(--border);
  border-radius: 18px;
  background: #fff;
  box-shadow: var(--shadow);
}

.employee-side-photo {
  width: 142px;
  height: 142px;
  margin: 0 auto;
  border: 3px dashed #cfdae7;
  background: #fafbfd;
  color: #9aa9be;
  box-shadow: none;
}

.employee-side-photo svg {
  width: 43px;
}

.employee-photo-upload {
  display: inline-flex;
  min-height: 39px;
  align-items: center;
  align-self: center;
  justify-content: center;
  gap: 7px;
  margin-top: 12px;
  padding: 0 18px;
  border-radius: 22px;
  background: var(--sidebar-bg);
  color: #fff;
  font-size: 11px;
  box-shadow: 0 8px 20px rgba(13, 23, 44, 0.21);
}

.employee-photo-upload svg {
  width: 16px;
}

.employee-photo-remove {
  align-self: center;
  margin-top: 8px;
  font-size: 9px;
}

.employee-side-stat {
  display: flex;
  min-height: 72px;
  margin-top: 13px;
  padding: 11px 13px;
  border: 1px solid #e0e5ec;
  border-radius: 13px;
  background: #fbfcfe;
  flex-direction: column;
}

.employee-side-stat + .employee-side-stat {
  min-height: 60px;
  margin-top: 9px;
}

.employee-side-label {
  margin: 0;
  color: #717b8c;
  font-size: 10px;
}

.employee-side-number,
.employee-side-service {
  margin: 5px 0 0;
  color: #1c2434;
  font-size: 15px;
}

.employee-side-stat small {
  margin-top: 5px;
  color: #a0a8b6;
  font-size: 8px;
  line-height: 1.55;
}

.employee-section-nav {
  margin-top: 18px;
  padding-top: 16px;
}

.employee-section-nav button {
  min-height: 40px;
  padding: 0 13px;
  border-radius: 10px;
  color: #414a5d;
  font-size: 11px;
}

.employee-section-nav button svg {
  display: none;
}

.employee-section-nav button:hover {
  background: #f2f6fa;
}

.employee-section-nav button.active {
  background: linear-gradient(100deg, var(--accent-blue), var(--accent-green));
  color: #fff;
  box-shadow: 0 7px 19px rgba(24, 184, 170, 0.17);
}

.employee-section-content {
  padding: 0;
}

.employee-tab-panel {
  min-height: 100%;
  padding: 0 22px 24px;
  border: 1px solid var(--border);
  border-radius: 18px;
  background: #fff;
  box-shadow: var(--shadow);
}

.employee-tab-panel .form-section-title {
  min-height: 58px;
  margin: 0 -22px 24px;
  padding: 0 22px;
  border-bottom: 1px solid var(--border);
}

.form-section-title > span:first-child {
  width: 31px;
  height: 31px;
  border-radius: 8px;
  background: transparent;
  color: #147d91;
}

.form-section-title h3 {
  color: #13778c;
  font-size: 16px;
}

.form-section-title p {
  display: none;
}

.employee-tab-panel .form-grid {
  gap: 20px 17px;
}

.employee-tab-panel .form-grid label > span,
.employee-tab-panel .choice-field legend {
  color: #434c5f;
  font-size: 11px;
}

.employee-tab-panel .form-grid input,
.employee-tab-panel .form-grid select,
.employee-tab-panel .form-grid textarea,
.repeatable-row input,
.repeatable-row select {
  min-height: 47px;
  border-color: #d5dce6;
  border-radius: 11px;
  background: #fbfcfe;
  color: #1f2839;
  font-size: 12px;
}

.employee-tab-panel .form-grid input:focus,
.employee-tab-panel .form-grid select:focus,
.employee-tab-panel .form-grid textarea:focus,
.repeatable-row input:focus,
.repeatable-row select:focus {
  border-color: var(--accent-blue);
  box-shadow: 0 0 0 3px rgba(24, 174, 225, 0.1);
}

.choice-cards {
  display: flex;
  min-height: 47px;
  align-items: center;
  gap: 16px;
}

.choice-cards label {
  display: inline-flex;
  flex: 0 0 auto;
}

.choice-cards input {
  position: static;
  width: 17px;
  height: 17px;
  margin-left: 6px;
  opacity: 1;
  accent-color: var(--accent-blue);
}

.choice-cards span {
  min-height: 0;
  padding: 0;
  border: 0;
  background: transparent !important;
  color: #444d60;
  font-size: 12px;
  box-shadow: none !important;
}

.choice-cards input:checked + span {
  color: #263044;
}

.calculated-field {
  border-color: #d5dce6 !important;
  background: #f4f6f9 !important;
  color: #596477 !important;
}

.employee-profile-modal .modal-actions {
  min-height: 82px;
  margin: 0 28px 18px calc(310px + 45px);
  padding: 16px 22px;
  border: 1px solid var(--border);
  border-radius: 18px;
  background: #fff;
  box-shadow: var(--shadow);
}

.employee-profile-modal .modal-actions .primary-btn {
  order: -1;
  min-width: 190px;
}

.employee-profile-modal .modal-actions .secondary-btn {
  min-width: 85px;
}

.commission-pay-btn,
.print-icon-btn,
.quick-view-btn {
  background: linear-gradient(100deg, var(--accent-blue), var(--accent-green));
  color: #fff;
}

.compact-file-control.has-file,
.expiry-state.valid,
.consent-issued-card {
  border-color: #a8e2d1 !important;
  background: #effcf7 !important;
  color: #12835f !important;
}

@media (max-width: 1180px) {
  :root {
    --sidebar-width: 235px;
  }

  .employee-workspace {
    grid-template-columns: 260px minmax(0, 1fr);
  }

  .employee-profile-modal .modal-actions {
    margin-right: calc(260px + 45px);
  }
}

@media (max-width: 900px) {
  .sidebar {
    z-index: 75;
  }

  .main-area {
    margin-right: 0;
  }

  .employee-profile-modal[open] {
    right: 0;
  }
}

@media (max-width: 720px) {
  :root {
    --topbar-height: 74px;
  }

  .topbar {
    min-height: var(--topbar-height);
    padding: 10px 14px;
  }

  .page-heading h1 {
    font-size: 17px;
  }

  .topbar-user-copy,
  .logout-btn {
    display: none;
  }

  .topbar-user-mark {
    width: 39px;
    height: 39px;
  }

  .content {
    padding: 18px 14px 38px;
  }

  .employee-profile-modal[open] {
    inset: var(--topbar-height) 0 0;
  }

  .employee-profile-modal .modal-head {
    min-height: 82px;
    padding: 16px 15px 10px;
  }

  .employee-profile-modal .modal-head h2 {
    font-size: 17px;
  }

  .employee-profile-modal .modal-head p {
    font-size: 9px;
  }

  .employee-workspace {
    padding: 0 12px 12px;
  }

  .employee-form-sidebar {
    border-radius: 14px;
  }

  .employee-side-photo {
    width: 66px;
    height: 66px;
  }

  .employee-side-stat {
    min-height: 0;
    margin: 0;
    padding: 7px 10px;
  }

  .employee-side-stat small {
    display: none;
  }

  .employee-section-nav button {
    min-height: 36px;
  }

  .employee-tab-panel {
    padding: 0 14px 18px;
    border-radius: 14px;
  }

  .employee-tab-panel .form-section-title {
    margin: 0 -14px 17px;
    padding: 0 14px;
  }

  .employee-profile-modal .modal-actions {
    min-height: 70px;
    margin: 0 12px 12px;
    padding: 12px;
  }

  .employee-profile-modal .modal-actions .primary-btn {
    min-width: 0;
  }
}

