.settings-section { display: none; }
.settings-section.active { display: block; }
.settings-placeholder-card {
  display: flex;
  gap: 14px;
  align-items: center;
  margin: 0 22px 22px;
  padding: 18px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: #fafcfc;
}
.settings-placeholder-card svg { width: 28px; color: var(--primary); }
.settings-placeholder-card strong { display: block; margin-bottom: 5px; color: var(--text); }
.settings-placeholder-card p { margin: 0; color: var(--muted); font-size: 11px; }
.permissions-preview-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding: 0 22px 22px;
}
.permission-preview-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 13px;
  border: 1px solid var(--border);
  border-radius: 14px;
  background: #fff;
}
.permission-preview-card strong { display: block; font-size: 12px; color: var(--text); }
.permission-preview-card span:not(.status-badge) { display: block; margin-top: 4px; color: var(--muted); font-size: 10px; }
.work-settings-form { display: grid; gap: 16px; }
.work-settings-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  padding-top: 4px;
}
.work-settings-summary > div {
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: linear-gradient(180deg, #ffffff, #f8fbfb);
}
.work-settings-summary span { display: block; color: var(--muted); font-size: 10px; }
.work-settings-summary strong { display: block; margin-top: 5px; color: var(--primary); font-size: 20px; }
.work-settings-block {
  padding: 15px;
  border: 1px solid var(--border);
  border-radius: 18px;
  background: #fff;
}
.shift-list,
.workday-list { display: grid; gap: 10px; }
.shift-row,
.workday-row {
  display: grid;
