/* v290 — complete branch profile; one read-only paint with no extra cloud request. */
.v290-branch-profile-modal {
  width: min(980px, calc(100vw - 28px)) !important;
  max-width: 980px !important;
  max-height: min(90vh, 880px);
  overflow: hidden;
  border-radius: 22px !important;
}

.v290-branch-profile-head {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto 38px;
  min-height: 88px;
  align-items: center !important;
  gap: 12px;
  padding: 16px 19px !important;
  background:
    radial-gradient(circle at 91% 12%, rgba(24, 184, 144, 0.14), transparent 29%),
    linear-gradient(135deg, #ffffff, #f3fbfb) !important;
}

.v290-branch-profile-title {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 11px;
}

.v290-branch-profile-title > div {
  display: grid;
  min-width: 0;
}

.v290-branch-profile-title h2,
.v290-branch-profile-title p {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.v290-branch-profile-mark {
  display: grid;
  width: 43px;
  height: 43px;
  flex: 0 0 43px;
  place-items: center;
  border: 1px solid #c9e7e8;
  border-radius: 14px;
  background: linear-gradient(145deg, #effafb, #edfaf5);
  color: #0b8e9e;
}

.v290-branch-profile-mark svg {
  width: 20px;
  height: 20px;
}

.v290-branch-profile-status {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border-radius: 999px;
  background: #eefaf5;
  color: #0d8963;
  font-size: 9px;
  font-weight: 900;
  white-space: nowrap;
}

.v290-branch-profile-status::before {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #17b579;
  box-shadow: 0 0 0 3px rgba(23, 181, 121, 0.11);
  content: "";
}

.v290-branch-profile-status.is-inactive {
  background: #f2f5f6;
  color: #7a898e;
}

.v290-branch-profile-status.is-inactive::before {
  background: #98a4a8;
  box-shadow: 0 0 0 3px rgba(152, 164, 168, 0.11);
}

.v290-branch-profile-body {
  display: grid !important;
  max-height: min(65vh, 650px);
  gap: 11px !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  padding: 13px 15px !important;
  background: #f5f9fa !important;
}

.v290-branch-profile-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
}

.v290-branch-profile-summary > article {
  position: relative;
  display: flex;
  min-width: 0;
  min-height: 82px;
  align-items: center;
  gap: 10px;
  overflow: hidden;
  padding: 12px 13px;
  border: 1px solid #dce8eb;
  border-radius: 15px;
  background: #fff;
  box-shadow: 0 7px 22px rgba(25, 63, 71, 0.035);
}

.v290-branch-profile-summary > article::after {
  position: absolute;
  inset-inline-start: 0;
  top: 17px;
  bottom: 17px;
  width: 3px;
  border-radius: 99px;
  background: #14a8c0;
  content: "";
}

.v290-branch-profile-summary > article:nth-child(2)::after {
  background: #19b879;
}

.v290-branch-profile-summary > article:nth-child(3)::after {
  background: #0e8798;
}

.v290-branch-profile-summary > article > span {
  display: grid;
  width: 39px;
  height: 39px;
  flex: 0 0 39px;
  place-items: center;
  border-radius: 12px;
  background: #edf9fb;
  color: #0b91a6;
}

.v290-branch-profile-summary > article > span.is-green {
  background: #edf9f3;
