/* v293 - professional cloud-backed personal account */
#settingsView [data-settings-panel="account"].active > :not(.v293-account-page) {
  display: none !important;
}

.v293-account-page {
  --v293-ink: #10263b;
  --v293-muted: #708398;
  --v293-line: #dce8ef;
  --v293-blue: #11a8c8;
  --v293-green: #1cc678;
  direction: rtl;
  color: var(--v293-ink);
  min-height: 520px;
}

.v293-account-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin: 0 0 18px;
  padding: 4px 2px 16px;
  border-bottom: 1px solid var(--v293-line);
}

.v293-account-head-title,
.v293-card-head,
.v293-avatar-identity,
.v293-security-line,
.v293-session-device {
  display: flex;
  align-items: center;
  gap: 12px;
}

.v293-account-head-mark,
.v293-card-head > span:first-child {
  width: 46px;
  height: 46px;
  min-width: 46px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  color: #087f98;
  border: 1px solid #c8edf3;
  background: linear-gradient(145deg, #eefcff, #effcf5);
}

.v293-account-head-mark svg,
.v293-card-head > span:first-child svg {
  width: 22px;
  height: 22px;
}

.v293-account-head h3,
.v293-card-head h4 {
  margin: 0;
  color: var(--v293-ink);
}

.v293-account-head h3 {
  font-size: 20px;
  font-weight: 900;
}

.v293-account-head p,
.v293-card-head p {
  margin: 4px 0 0;
  color: var(--v293-muted);
  line-height: 1.7;
}

.v293-account-head p { font-size: 13px; }
.v293-card-head h4 { font-size: 16px; font-weight: 900; }
.v293-card-head p { font-size: 12px; }

.v293-cloud-state {
  min-height: 34px;
  padding: 7px 12px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: #effaf5;
  border: 1px solid #c9efdc;
  color: #118653;
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
}

.v293-cloud-state.is-saving {
  color: #087f98;
  background: #edfaff;
  border-color: #c8ebf3;
}

.v293-cloud-state.is-error {
  color: #c53030;
  background: #fff5f5;
  border-color: #fecaca;
}

.v293-cloud-state svg { width: 16px; height: 16px; }

.v293-account-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  align-items: stretch;
}

.v293-account-card {
  min-width: 0;
  border: 1px solid var(--v293-line);
  border-radius: 24px;
  background: linear-gradient(180deg, #fff, #fbfdff);
  box-shadow: 0 16px 38px rgba(15, 47, 66, .055);
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.v293-account-card::before {
  content: "";
  height: 3px;
  margin: -18px -18px 0;
  border-radius: 24px 24px 0 0;
  background: linear-gradient(90deg, var(--v293-blue), var(--v293-green));
}

.v293-card-head {
  align-items: flex-start;
  min-height: 50px;
}

.v293-avatar-block {
  border: 1px solid #e1edf3;
  border-radius: 20px;
  padding: 14px;
  background: linear-gradient(145deg, #f7fcff, #f7fdf9);
}

.v293-avatar-identity { align-items: center; }

.v293-avatar-preview {
  width: 82px;
  height: 82px;
  min-width: 82px;
  border-radius: 24px;
  overflow: hidden;
  display: grid;
  place-items: center;
  background: linear-gradient(145deg, #0fa8c7, #20c878);
  color: #fff;
  font-size: 27px;
  font-weight: 900;
  box-shadow: 0 12px 26px rgba(14, 165, 183, .16);
}

.v293-avatar-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.v293-avatar-copy { min-width: 0; }
.v293-avatar-copy strong {
  display: block;
  font-size: 15px;
  line-height: 1.65;
  color: var(--v293-ink);
  overflow-wrap: anywhere;
}
.v293-avatar-copy span {
  display: block;
  margin-top: 3px;
  font-size: 11.5px;
  color: var(--v293-muted);
  direction: ltr;
  text-align: right;
  overflow-wrap: anywhere;
}

.v293-avatar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
}

.v293-avatar-upload,
.v293-icon-action {
  height: 38px;
  border-radius: 12px;
  font-family: inherit;
  font-size: 12px;
  font-weight: 900;
  cursor: pointer;
  transition: .15s ease;
}

.v293-avatar-upload {
  position: relative;
  flex: 1;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 7px;
  color: #087f98;
  background: #fff;
  border: 1px solid #bfe5ed;
  overflow: hidden;
}

.v293-avatar-upload input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}

.v293-avatar-upload svg,
.v293-icon-action svg { width: 17px; height: 17px; }

.v293-icon-action {
  width: 38px;
  min-width: 38px;
  padding: 0;
  display: grid;
  place-items: center;
  background: #fff;
  border: 1px solid #d8e7ee;
  color: #0a8ca4;
}

.v293-icon-action.is-danger {
  color: #dc3d3d;
  border-color: #fecaca;
}

.v293-avatar-upload:hover,
.v293-icon-action:hover { transform: translateY(-1px); background: #f5fcfe; }
.v293-avatar-upload.is-busy { opacity: .65; pointer-events: none; }

.v293-fields { display: grid; gap: 12px; }
.v293-fields.two { grid-template-columns: repeat(2, minmax(0, 1fr)); }

.v293-field { display: grid; gap: 7px; min-width: 0; }
.v293-field > span {
  font-size: 12px;
  font-weight: 900;
  color: #52687b;
}

.v293-field input,
.v293-field select {
  width: 100%;
  height: 44px;
  min-width: 0;
  border: 1px solid #d8e5ed;
  border-radius: 14px;
  padding: 0 12px;
  outline: none;
  background: #fff;
  color: var(--v293-ink);
  font-family: inherit;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.4;
}

.v293-field input:focus,
.v293-field select:focus {
  border-color: #6fd0df;
  box-shadow: 0 0 0 4px rgba(14, 165, 183, .09);
}

.v293-field input[readonly],
.v293-readonly {
  background: #f6f9fb !important;
  color: #52687b !important;
  cursor: default;
}

.v293-readonly-line {
  min-height: 44px;
  border: 1px solid #d8e5ed;
  border-radius: 14px;
  padding: 8px 11px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  background: #f6f9fb;
  color: #30495d;
  font-size: 12px;
  font-weight: 800;
}

.v293-readonly-line strong { overflow-wrap: anywhere; }
.v293-mini-open {
  width: 31px;
  height: 31px;
  min-width: 31px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  border: 1px solid #c9e8ee;
  background: #fff;
  color: #0887a0;
  cursor: pointer;
}
.v293-mini-open svg { width: 15px; height: 15px; }

.v293-card-actions {
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid #edf2f5;
  display: flex;
  align-items: center;
  gap: 9px;
}

.v293-primary,
.v293-secondary,
.v293-danger {
  min-height: 42px;
  border-radius: 13px;
  padding: 0 15px;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  font-family: inherit;
  font-size: 12.5px;
  font-weight: 900;
  cursor: pointer;
}

.v293-primary {
  border: 0;
  color: #fff;
  background: linear-gradient(110deg, #12a9c9, #20c878);
  box-shadow: 0 10px 22px rgba(13, 168, 186, .16);
}
.v293-secondary { border: 1px solid #d6e5ec; background: #fff; color: #315069; }
.v293-danger { border: 1px solid #fecaca; background: #fff5f5; color: #c53030; }
.v293-primary:disabled,
.v293-secondary:disabled,
.v293-danger:disabled { opacity: .58; cursor: wait; }
.v293-primary svg,
.v293-secondary svg,
.v293-danger svg { width: 17px; height: 17px; }

.v293-security-summary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}
.v293-security-summary article {
  border: 1px solid #e1ebf1;
  border-radius: 15px;
  background: #f8fbfd;
  padding: 11px;
  min-width: 0;
}
.v293-security-summary span { display: block; color: var(--v293-muted); font-size: 10.5px; font-weight: 800; }
.v293-security-summary strong { display: block; margin-top: 5px; color: #263f54; font-size: 12px; line-height: 1.6; overflow-wrap: anywhere; }

.v293-password-strength {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
  align-items: center;
}
.v293-password-strength i { height: 4px; border-radius: 99px; background: #e3ebf0; }
.v293-password-strength[data-score="1"] i:nth-child(-n+1),
.v293-password-strength[data-score="2"] i:nth-child(-n+2) { background: #f59e0b; }
.v293-password-strength[data-score="3"] i:nth-child(-n+3),
.v293-password-strength[data-score="4"] i:nth-child(-n+4) { background: #19b875; }
.v293-strength-copy { margin-top: -4px; color: var(--v293-muted); font-size: 10.5px; }

.v293-toggle-list { display: grid; gap: 9px; }
.v293-toggle-row {
  min-height: 52px;
  padding: 10px 11px;
  border: 1px solid #e0ebf1;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: #fbfdfe;
}
.v293-toggle-row strong { display: block; font-size: 12.5px; color: #263f54; }
.v293-toggle-row small { display: block; margin-top: 3px; color: var(--v293-muted); font-size: 10.5px; line-height: 1.55; }
.v293-toggle-row input { width: 19px; height: 19px; accent-color: #13ac8a; flex: 0 0 auto; }

.v293-settings-note {
  border: 1px dashed #cce7ed;
  border-radius: 15px;
  background: #f4fcfd;
  padding: 10px 12px;
  color: #4f7180;
  font-size: 11px;
  line-height: 1.75;
}

.v293-session-dialog {
  width: min(560px, calc(100vw - 24px));
  border: 0;
  border-radius: 24px;
  padding: 0;
  overflow: hidden;
  box-shadow: 0 34px 90px rgba(15, 34, 52, .27);
}
.v293-session-dialog::backdrop { background: rgba(15, 34, 52, .48); backdrop-filter: blur(4px); }
.v293-session-dialog header { padding: 20px; display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; border-bottom: 1px solid #e6eef3; background: linear-gradient(145deg, #f4fdff, #f4fcf7); }
.v293-session-dialog h3 { margin: 0; font-size: 18px; color: var(--v293-ink); }
.v293-session-dialog header p { margin: 5px 0 0; font-size: 12px; color: var(--v293-muted); }
.v293-session-close { width: 36px; height: 36px; border-radius: 11px; border: 1px solid #d7e5ec; background: #fff; display: grid; place-items: center; cursor: pointer; }
.v293-session-close svg { width: 17px; height: 17px; }
.v293-session-body { padding: 20px; display: grid; gap: 13px; }
.v293-session-current { border: 1px solid #cbeade; border-radius: 18px; background: #f1fbf6; padding: 14px; }
.v293-session-current > span { width: 42px; height: 42px; border-radius: 14px; display: grid; place-items: center; background: #fff; color: #0b9570; }
.v293-session-current svg { width: 20px; height: 20px; }
.v293-session-current strong { display: block; font-size: 13px; color: #1d493c; }
.v293-session-current small { display: block; margin-top: 4px; color: #628277; font-size: 11px; line-height: 1.6; }
.v293-session-note { margin: 0; color: #687d8f; font-size: 11.5px; line-height: 1.8; }
.v293-session-confirm { border: 1px solid #fed7aa; background: #fff9ed; color: #9a5b16; border-radius: 15px; padding: 11px 12px; font-size: 11.5px; line-height: 1.7; }
.v293-session-actions { padding: 15px 20px 20px; display: flex; justify-content: flex-start; gap: 9px; }

html[data-v293-reduced-motion="1"] *,
html[data-v293-reduced-motion="1"] *::before,
html[data-v293-reduced-motion="1"] *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; scroll-behavior: auto !important; }

@media (max-width: 1250px) {
  .v293-account-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .v293-preferences-card { grid-column: 1 / -1; }
