.dashboard-command-grid-v362 {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 18px;
  margin-top: 18px;
}

.dashboard-command-grid-v362 > .panel {
  min-width: 0;
  border: 1px solid var(--dashboard-line-v362);
  border-radius: 22px;
  box-shadow: 0 12px 32px rgba(26, 74, 97, 0.08);
}

.dashboard-section-kicker-v362 {
  display: inline-flex;
  margin-bottom: 5px;
  color: #2297c5;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.dashboard-team-total-v362 {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 16px 18px;
  border-radius: 18px;
  background: linear-gradient(135deg, rgba(34, 151, 197, 0.09), rgba(34, 197, 94, 0.08));
}

.dashboard-team-total-v362 > div:first-child {
  display: grid;
  gap: 4px;
}

.dashboard-team-total-v362 strong {
  color: var(--dashboard-ink-v362);
  font-size: 31px;
  line-height: 1;
}

.dashboard-team-total-v362 span {
  color: var(--dashboard-muted-v362);
  font-size: 12px;
}

.dashboard-team-ring-v362 {
  width: 68px;
  height: 68px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #168eaa;
  background: radial-gradient(circle at center, #fff 58%, transparent 60%),
    conic-gradient(#22c58a calc(var(--team-rate) * 1%), #dcecf1 0);
}

.dashboard-team-ring-v362 svg {
  width: 25px;
  height: 25px;
}

.dashboard-team-states-v362 {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 9px;
  margin-top: 13px;
}

.dashboard-team-states-v362 button {
  appearance: none;
  display: grid;
  gap: 7px;
  min-width: 0;
  padding: 12px 9px;
  border: 1px solid #e6eef2;
  border-radius: 14px;
  background: #fff;
  color: var(--dashboard-muted-v362);
  cursor: pointer;
  text-align: right;
  transition: background 160ms ease, border-color 160ms ease, transform 160ms ease;
}

.dashboard-team-states-v362 button:hover {
  transform: translateY(-2px);
  background: #f7fbfc;
  border-color: rgba(34, 151, 197, 0.3);
}

.dashboard-team-states-v362 button strong {
  color: var(--dashboard-ink-v362);
  font-size: 20px;
}

.dashboard-team-states-v362 button::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #22c55e;
}

.dashboard-team-states-v362 .is-absent::before { background: #ef4444; }
.dashboard-team-states-v362 .is-leave::before { background: #facc15; }
.dashboard-team-states-v362 .is-travel::before { background: #2297c5; }

.dashboard-finance-hero-v362 {
  display: grid;
  gap: 6px;
  padding: 17px 18px;
  border-radius: 18px;
  color: #fff;
  background: linear-gradient(125deg, #153e59, #147f9f 68%, #18a995);
  box-shadow: inset 0 1px rgba(255, 255, 255, 0.15);
}

.dashboard-finance-hero-v362 span,
.dashboard-finance-hero-v362 small { color: rgba(255, 255, 255, 0.78); }
.dashboard-finance-hero-v362 strong { font-size: 27px; }

.dashboard-finance-metrics-v362 {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
  margin-top: 12px;
}

.dashboard-finance-metrics-v362 > div {
  display: grid;
  gap: 7px;
  padding: 12px;
  border: 1px solid #e7eff2;
  border-radius: 14px;
  background: #fbfdfe;
}

.dashboard-finance-metrics-v362 span {
  color: var(--dashboard-muted-v362);
  font-size: 11px;
}

.dashboard-finance-metrics-v362 strong {
  color: var(--dashboard-ink-v362);
  font-size: 14px;
  white-space: nowrap;
}

.dashboard-budget-state-v362 {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 11px;
  padding: 10px 12px;
  border-radius: 12px;
  color: #16815d;
  background: #ecfdf5;
  font-size: 12px;
}

.dashboard-budget-state-v362.is-unmatch {
  color: #a16207;
  background: #fffbeb;
}

#dashboardView .dashboard-grid > .panel,
#dashboardView .recent-panel,
#dashboardView .expiry-dashboard-panel {
  border: 1px solid var(--dashboard-line-v362);
  border-radius: 22px;
  box-shadow: 0 12px 32px rgba(26, 74, 97, 0.07);
}

@media (max-width: 1050px) {
  .dashboard-command-grid-v362 { grid-template-columns: 1fr; }
}

@media (max-width: 680px) {
  .dashboard-team-states-v362 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dashboard-finance-metrics-v362 { grid-template-columns: 1fr; }
  #dashboardView .dashboard-welcome-compact .welcome-copy { align-items: stretch; }
  #dashboardView .dashboard-welcome-compact .banner-action { flex: 1 1 calc(50% - 10px); }
}
/* Dashboard quick actions bar v363 */
.dashboard-actions-bar-v363 {
  direction: ltr;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  flex-wrap: wrap;
  gap: 10px;
  margin: 12px 0 18px;
  padding: 11px 13px;
  border: 1px solid rgba(34, 151, 197, 0.16);
  border-radius: 17px;
  background: linear-gradient(115deg, rgba(255, 255, 255, 0.98), rgba(237, 249, 251, 0.96));
  box-shadow: 0 8px 24px rgba(26, 74, 97, 0.07);
}

.dashboard-actions-bar-v363 .banner-action {
  direction: rtl;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 148px;
  min-height: 42px;
  margin: 0;
  padding: 9px 16px;
  border: 1px solid rgba(34, 151, 197, 0.22);
  border-radius: 12px;
  background: #fff;
  color: #167fa6;
  font-family: inherit;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 5px 14px rgba(34, 151, 197, 0.07);
  transition: transform 160ms ease, color 160ms ease, background 160ms ease, box-shadow 160ms ease;
}

.dashboard-actions-bar-v363 .banner-action:first-child {
  border-color: transparent;
  background: linear-gradient(135deg, #2297c5, #18a7b5);
  color: #fff;
}

.dashboard-actions-bar-v363 .banner-absence-action {
  color: #c2414b;
  border-color: rgba(239, 68, 68, 0.2);
  background: #fffafa;
}

.dashboard-actions-bar-v363 .banner-advance-action {
  color: #16815d;
  border-color: rgba(34, 197, 94, 0.22);
  background: #f6fdf9;
}

.dashboard-actions-bar-v363 .banner-action:hover {
  transform: translateY(-2px);
  color: #fff;
  border-color: transparent;
  background: linear-gradient(135deg, #147fa2, #18a995);
  box-shadow: 0 9px 20px rgba(34, 151, 197, 0.17);
}

.dashboard-actions-bar-v363 .banner-action svg {
  width: 17px;
  height: 17px;
}

@media (max-width: 680px) {
  .dashboard-actions-bar-v363 {
    display: grid;
    grid-template-columns: 1fr;
  }

  .dashboard-actions-bar-v363 .banner-action {
    width: 100%;
  }
}
/* Operational dashboard layout v364 */
#dashboardView.view.active {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 18px;
  align-items: start;
}

#dashboardView > .dashboard-welcome-compact,
#dashboardView > .dashboard-actions-bar-v363,
#dashboardView > .stats-grid,
#dashboardView > .dashboard-insights-v364,
#dashboardView > .recent-panel {
  grid-column: 1 / -1;
}

#dashboardView > .dashboard-welcome-compact { order: 1; }
#dashboardView > .dashboard-actions-bar-v363 { order: 2; margin: -6px 0 0; }
#dashboardView > .stats-grid { order: 3; }
#dashboardView > .dashboard-grid,
#dashboardView > .dashboard-command-grid-v362 { display: contents; }
#dashboardView .leave-panel { order: 4; grid-column: span 4; }
#dashboardView .dashboard-team-panel-v362 { order: 4; grid-column: span 2; }
#dashboardView .travelers-dashboard-panel { order: 5; grid-column: 1 / -1; }
#dashboardView > .dashboard-insights-v364 { order: 6; }
#dashboardView #dashboardEstDocsPanel,
#dashboardView #dashboardEmployeeDocsPanel { order: 7; grid-column: span 3; }
#dashboardView .dashboard-finance-panel-v362 { order: 8; grid-column: 1 / -1; }
#dashboardView > .recent-panel { order: 9; }

#dashboardView .stats-grid {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.dashboard-action-summary-v364 {
  display: inline-flex;
  width: fit-content;
  margin-top: 3px;
  padding: 7px 11px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.94);
  font-size: 11px;
  font-weight: 700;
}

.stat-card-attention-v364 {
  background: linear-gradient(145deg, #fff, #fffaf0);
}

.dashboard-insights-v364 {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.dashboard-insight-card-v364 {
  appearance: none;
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
  padding: 15px;
  border: 1px solid rgba(34, 151, 197, 0.14);
  border-radius: 17px;
  background: #fff;
  box-shadow: 0 9px 25px rgba(26, 74, 97, 0.07);
  cursor: pointer;
  transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease;
}

.dashboard-insight-card-v364:hover {
  transform: translateY(-3px);
  border-color: rgba(34, 151, 197, 0.32);
  box-shadow: 0 14px 30px rgba(26, 74, 97, 0.12);
}

.dashboard-insight-card-v364 > span {
  display: grid;
  place-items: center;
  flex: 0 0 44px;
  width: 44px;
  height: 44px;
  border-radius: 13px;
  color: #168eaa;
  background: #eaf8fb;
}

.dashboard-insight-card-v364.is-contract > span { color: #a16207; background: #fff7df; }
.dashboard-insight-card-v364.is-absence > span { color: #c2414b; background: #fff0f1; }
.dashboard-insight-card-v364.is-finance > span { color: #16815d; background: #ecfdf5; }
.dashboard-insight-card-v364 > span svg { width: 21px; height: 21px; }
.dashboard-insight-card-v364 > div { display: grid; gap: 3px; min-width: 0; }
.dashboard-insight-card-v364 small { color: #6b7f8f; font-size: 11px; }
.dashboard-insight-card-v364 strong { color: #123047; font-size: 21px; line-height: 1.2; }
.dashboard-insight-card-v364 p { margin: 0; color: #80909b; font-size: 10px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

#dashboardView .leave-panel,
#dashboardView .dashboard-team-panel-v362 {
  min-height: 100%;
}

#dashboardView .dashboard-finance-panel-v362 .dashboard-finance-hero-v362 {
  grid-template-columns: 1fr auto;
  align-items: center;
}

#dashboardView .dashboard-finance-panel-v362 .dashboard-finance-hero-v362 small {
  grid-column: 1 / -1;
}

#dashboardView .recent-panel tbody tr {
  transition: background 140ms ease;
}

#dashboardView .recent-panel tbody tr:hover { background: #f7fbfc; }

@media (max-width: 1180px) {
  #dashboardView .stats-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .dashboard-insights-v364 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 900px) {
  #dashboardView.view.active { grid-template-columns: 1fr; }
  #dashboardView .leave-panel,
  #dashboardView .dashboard-team-panel-v362,
  #dashboardView .travelers-dashboard-panel,
  #dashboardView #dashboardEstDocsPanel,
  #dashboardView #dashboardEmployeeDocsPanel,
  #dashboardView .dashboard-finance-panel-v362 { grid-column: 1; }
}

@media (max-width: 680px) {
  #dashboardView .stats-grid,
  .dashboard-insights-v364 { grid-template-columns: 1fr; }
}

/* Finance fund status: preserve the signed value internally while presenting
   a clear Arabic label and absolute amount when the balance is a deficit. */
.finance-summary-card.finance-fund-highlight.finance-negative{
  background:linear-gradient(135deg,#fff1f2 0%,#ffffff 46%,#fee2e2 100%);
  border-color:rgba(220,38,38,.34)!important;
  box-shadow:0 12px 26px rgba(220,38,38,.12)!important;
}
.finance-summary-card.finance-fund-highlight.finance-negative::before{
  background:linear-gradient(180deg,#b91c1c,#ef4444,#fca5a5);
}
.finance-summary-card.finance-fund-highlight.finance-negative span{
  color:#b91c1c;
}
.finance-summary-card.finance-fund-highlight.finance-negative strong{
  color:#991b1b;
}
.finance-summary-card.finance-fund-highlight.finance-negative small{
  color:#b91c1c;
}
.finance-summary-card.finance-fund-highlight.finance-zero{
  background:linear-gradient(135deg,#f8fafc 0%,#ffffff 55%,#f1f5f9 100%);
  border-color:rgba(148,163,184,.30)!important;
}

