.finance-summary-card.finance-fund-highlight.finance-negative{
  background:linear-gradient(135deg,#fff1f2 0%,#ffffff 46%,#fee2e2 100%);
  border-color:rgba(220,38,38,.34)!important;
  box-shadow:0 12px 26px rgba(220,38,38,.12)!important;
}
.finance-summary-card.finance-fund-highlight.finance-negative::before{
  background:linear-gradient(180deg,#b91c1c,#ef4444,#fca5a5);
}
.finance-summary-card.finance-fund-highlight.finance-negative span{color:#b91c1c}
.finance-summary-card.finance-fund-highlight.finance-negative strong{color:#991b1b}
.finance-summary-card.finance-fund-highlight.finance-negative small{color:#b91c1c}
.finance-summary-card.finance-fund-highlight.finance-zero{
  background:linear-gradient(135deg,#f8fafc 0%,#ffffff 55%,#f1f5f9 100%);
  border-color:rgba(148,163,184,.30)!important;
}
